// PANNEAU FILTRES
// ═══════════════════════════════════════════════════

function initFiltersToggle() {
  const trigger = document.getElementById('filters-trigger');
  const body = document.getElementById('filters-body');
  const chevron = document.getElementById('filters-chevron');
  if (!trigger || !body || !chevron) return;
  trigger.addEventListener('click', () => {
    const isOpen = body.classList.toggle('is-open');
    chevron.classList.toggle('is-open', isOpen);
  });
}

// ═══════════════════════════════════════════════════
// SELECT SITE → RÉFÉRENTIELS SÉQUENTIELS
// ═══════════════════════════════════════════════════

function initSiteSelect() {
  const selectSite = document.getElementById('select-site');
  if (!selectSite) return;
  selectSite.addEventListener('change', async () => {
    const code = selectSite.value;
    resetRefSelects();
    if (!code) return;
    await loadAllReferentiels(code);
  });
}
function resetRefSelects() {
  document.querySelectorAll('.filter-field__select--ref').forEach(select => {
    select.innerHTML = '<option value="">Tous</option>';
    select.disabled = true;
    select.dataset.loaded = 'false';
  });
}
async function loadAllReferentiels(code) {
  const types = [{
    type: 'mouvement',
    key: 'mouvement',
    selectId: 'select-mouvement'
  }, {
    type: 'produit',
    key: 'produit',
    selectId: 'select-produit'
  }, {
    type: 'client',
    key: 'client',
    selectId: 'select-client'
  }, {
    type: 'fournisseur',
    key: 'fournisseur',
    selectId: 'select-fournisseur'
  }, {
    type: 'transporteur',
    key: 'transporteur',
    selectId: 'select-transporteur'
  }, {
    type: 'destination',
    key: 'destination',
    selectId: 'select-destination'
  }, {
    type: 'provenance',
    key: 'provenance',
    selectId: 'select-provenance'
  }, {
    type: 'vehicule',
    key: 'immatriculation',
    selectId: 'select-vehicule'
  }];
  for (const {
    type,
    key,
    selectId
  } of types) {
    const select = document.getElementById(selectId);
    if (!select) continue;
    select.innerHTML = '<option value="">Chargement…</option>';
    select.disabled = true;
    try {
      const res = await fetch(`/referentiels/${encodeURIComponent(code)}/${type}`, {
        credentials: 'include'
      });
      if (!res.ok) throw new Error(`HTTP ${res.status}`);
      const data = await res.json();
      select.innerHTML = '<option value="">Tous</option>';
      data.forEach(item => {
        const val = item[key] ?? '';
        if (!val) return;
        const opt = document.createElement('option');
        opt.value = val;
        opt.textContent = val;
        select.appendChild(opt);
      });
      select.disabled = false;
      select.dataset.loaded = code;
    } catch (err) {
      console.error(`Erreur chargement ${type}:`, err);
      select.innerHTML = '<option value="">Erreur</option>';
      select.disabled = false;
    }
  }
}

