// COLLECTE DONNÉES TABLEAU
// ═══════════════════════════════════════════════════

function collectTableData() {
  const table = document.getElementById('operations-table');
  if (!table) return {
    headers: [],
    rows: []
  };
  const headers = [...table.querySelectorAll('thead th')].map(th => th.textContent.trim());
  const rows = [...table.querySelectorAll('tbody tr')].filter(tr => !tr.querySelector('.col-empty')).map(tr => [...tr.querySelectorAll('td')].map(td => {
    const clone = td.cloneNode(true);
    clone.querySelectorAll('.cell-sub').forEach(el => el.remove());
    return clone.textContent.trim().replace(/\s+/g, ' ');
  }));
  return {
    headers,
    rows
  };
}

